    "question_latex": "Solve for $x$: $\\frac{1}{a+b+x} = \\frac{1}{a} + \\frac{1}{b} + \\frac{1}{x}$ ($a\\ne 0, b\\ne 0, x\\ne 0, a+b+x\\ne 0$).",
    "options_latex": [],
    "correct_answer_latex": "x = -a, -b",
    "solution_latex": "$\\frac{1}{a+b+x} - \\frac{1}{x} = \\frac{1}{a} + \\frac{1}{b} \\implies \\frac{x - (a+b+x)}{x(a+b+x)} = \\frac{a+b}{ab} \\implies \\frac{-(a+b)}{x(a+b+x)} = \\frac{a+b}{ab}$. Dividing by $(a+b)$: $-ab = x^2 + (a+b)x \\implies x^2 + (a+b)x + ab = 0 \\implies (x+a)(x+b) = 0 \\implies x = -a, -b$.",
    "socratic_hints": [
      "Recall the key theorems and formulas of Quadratic Equations.",
      "Apply the foundational step for Algebraic Fraction Solving.",
      "Substitute the given numerical values and simplify step by step."
    ]
