    "benchmark_time_seconds": 90,
    "marks_weightage": 2,
    "question_latex": "The probability of guessing the correct answer to a certain question is $\\frac{x}{12}$. If the probability of not guessing the correct answer is $\\frac{2}{3}$, find $x$.",
    "options_latex": [],
    "correct_answer_latex": "4",
    "solution_latex": "$P(E) + P(\\text{not } E) = 1 \\implies \\frac{x}{12} + \\frac{2}{3} = 1 \\implies \\frac{x}{12} = 1 - \\frac{2}{3} = \\frac{1}{3} \\implies x = 4$.",
