    "question_latex": "A boy is standing at a distance from a building. Angle of elevation is $45^\\circ$. After walking 10 m towards the building, the angle becomes $60^\\circ$.\\n(i) State trigonometric relations used.\\n(ii) Find the height of the building.\\n(iii) Find the original distance from the foot of the building.",
