    "benchmark_time_seconds": 180,
    "marks_weightage": 4,
    "question_latex": "A teacher wants to distribute 420 notebooks and 336 pens equally among students so that each student gets the same number of notebooks and pens with nothing left over.\\n(i) Which mathematical concept will help the teacher?\\n(ii) Find the maximum number of students who can get the items.\\n(iii) Find how many notebooks and pens each student will get.",
