    "benchmark_time_seconds": 180,
    "marks_weightage": 4,
    "question_latex": "A rectangular park is designed whose breadth is 3 m less than its length. Its area is 4 square metres more than the area of a square park of side 30 m.\\n(i) Form the quadratic equation.\\n(ii) Find the length of the rectangular park.\\n(iii) Find the breadth of the rectangular park.",
