    "benchmark_time_seconds": 180,
    "marks_weightage": 4,
    "question_latex": "The vertices of a triangle are $A(2, 3)$, $B(4, -1)$ and $C(-2, 1)$.\\n(i) Find the length of side $AB$.\\n(ii) Find the coordinates of the centroid.\\n(iii) Find the area of $\\triangle ABC$.",
    "options_latex": [],
    "correct_answer_latex": "(i) 2\\sqrt{5}, (ii) (4/3, 1), (iii) 10\\text{ sq units}",
    "solution_latex": "(i) $AB = \\sqrt{(4 - 2)^2 + (-1 - 3)^2} = \\sqrt{4 + 16} = \\sqrt{20} = 2\\sqrt{5}$.\\n(ii) Centroid $G = \\left(\\frac{2 + 4 - 2}{3}, \\frac{3 - 1 + 1}{3}\\right) = \\left(\\frac{4}{3}, 1\\right)$.\\n(iii) $\\text{Area} = \\frac{1}{2} |2(-1 - 1) + 4(1 - 3) - 2(3 - (-1))| = \\frac{1}{2} |-4 - 8 - 8| = 10\\text{ sq units}$.",
