    "benchmark_time_seconds": 180,
    "marks_weightage": 4,
    "question_latex": "From a point on the ground, the angles of elevation of the bottom and top of a transmission tower on a 20 m building are $45^\\circ$ and $60^\\circ$ respectively.\\n(i) Draw a rough diagram and state trigonometric ratios used.\\n(ii) Find the height of the transmission tower.\\n(iii) Find the distance of the point from the foot of the building.",
