    "benchmark_time_seconds": 180,
    "marks_weightage": 4,
    "question_latex": "From an external point P, two tangents PA and PB are drawn to a circle with centre O. $\\angle APB = 70^\\circ$.\\n(i) Find $\\angle AOB$.\\n(ii) Find $\\angle OAP$.\\n(iii) If radius of the circle is 5 cm and $OP = 13\\text{ cm}$, find the length of the tangent.",
    "options_latex": [],
    "correct_answer_latex": "(i) 110^\\circ, (ii) 90^\\circ, (iii) 12\\text{ cm}",
