    "solution_latex": "A number ends with 0 if its prime factorisation contains both 2 and 5. $6^n = (2 \\times 3)^n = 2^n \\times 3^n$. Since 5 is not a prime factor of $6^n$, by the Fundamental Theorem of Arithmetic, $6^n$ can never end with digit 0.",
