    "question_latex": "Prove that the following are irrational: (i) $\\frac{1}{\\sqrt{2}}$ (ii) $7\\sqrt{5}$ (iii) $6 + \\sqrt{2}$.",
    "options_latex": [],
    "correct_answer_latex": "Proof",
    "solution_latex": "(i) $\\frac{1}{\\sqrt{2}} = \\frac{\\sqrt{2}}{2}$. Since $\\sqrt{2}$ is irrational, $\\sqrt{2}/2$ is irrational. (ii) If $7\\sqrt{5} = a/b$, then $\\sqrt{5} = \\frac{a}{7b}$, which contradicts irrationality of $\\sqrt{5}$. (iii) If $6 + \\sqrt{2} = r$, then $\\sqrt{2} = r - 6$, contradiction.",
    "socratic_hints": [
      "Recall the key theorems and formulas of Real Numbers.",
      "Apply the foundational step for NCERT Example 15.",
      "Substitute the given numerical values and simplify step by step."
    ]
