    "benchmark_time_seconds": 180,
    "marks_weightage": 4,
    "question_latex": "Two poles of equal heights are standing opposite each other on either side of the road, which is 80 m wide. From a point between them on the road, the angles of elevation are $60^\\circ$ and $30^\\circ$. Find the height of the poles and distances from poles.",
    "options_latex": [],
