    "solution_latex": "Let height be $h$, distances be $x$ and $80 - x$. $\\tan 60^\\circ = h/x \\implies h = x\\sqrt{3}$. $\\tan 30^\\circ = h/(80 - x) \\implies \\frac{1}{\\sqrt{3}} = \\frac{x\\sqrt{3}}{80 - x} \\implies 80 - x = 3x \\implies x = 20\\text{ m}$. $h = 20\\sqrt{3}\\text{ m}$, distances: 20 m and 60 m.",
